import re
import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 200000))

    token_pat = re.compile(r'[A-Z]\d+|[A-Z]+|\d+|<>|<=|>=|[=<>+\-*/():,]')
    cell_pat = re.compile(r'[A-Z]\d+')
    compare = {
        '=': lambda a, b: a == b,
        '<>': lambda a, b: a != b,
        '<': lambda a, b: a < b,
        '<=': lambda a, b: a <= b,
        '>': lambda a, b: a > b,
        '>=': lambda a, b: a >= b,
    }
    values = {}
    busy = set()

    def is_cell(t):
        return t is not None and cell_pat.fullmatch(t) is not None

    def parse(text):
        toks = token_pat.findall(text)
        pos = [0]

        def peek(offset=0):
            i = pos[0] + offset
            return toks[i] if i < len(toks) else None

        def take():
            t = peek()
            pos[0] += 1
            return t

        def expr():
            node = term()
            while peek() in ('+', '-'):
                op = take()
                node = ('bin', op, node, term())
            return node

        def term():
            node = unary()
            while peek() in ('*', '/'):
                op = take()
                node = ('bin', op, node, unary())
            return node

        def unary():
            if peek() == '-':
                take()
                return ('neg', unary())
            return atom()

        def atom():
            t = take()
            if t.isdigit():
                return ('num', int(t))
            if t == '(':
                node = expr()
                take()  # ')'
                return node
            if t == 'IF':
                take()  # '('
                left = expr()
                op = take()
                right = expr()
                take()  # ','
                then = expr()
                take()  # ','
                other = expr()
                take()  # ')'
                return ('if', op, left, right, then, other)
            if t in ('SUM', 'MIN', 'MAX'):
                take()  # '('
                args = []
                while True:
                    if (is_cell(peek()) and peek(1) == ':' and is_cell(peek(2))
                            and peek(3) in (',', ')')):
                        c1 = take()
                        take()  # ':'
                        c2 = take()
                        args.append(('range', c1, c2))
                    else:
                        args.append(('expr', expr()))
                    if peek() == ',':
                        take()
                        continue
                    break
                take()  # ')'
                return ('call', t, args)
            return ('ref', t)

        return expr()

    def range_cells(c1, c2):
        r1, r2 = sorted((int(c1[1:]), int(c2[1:])))
        k1, k2 = sorted((ord(c1[0]), ord(c2[0])))
        for r in range(r1, r2 + 1):
            for k in range(k1, k2 + 1):
                name = chr(k) + str(r)
                if name in cells:
                    yield name

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in busy:
            return '#CYCLE!'
        busy.add(name)
        value = compute(name)
        busy.discard(name)
        values[name] = value
        return value

    def compute(name):
        text = cells[name].strip()
        if text.startswith('='):
            return evaluate(parse(text[1:]))
        return int(text)

    def evaluate(node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return cell_value(node[1])
        if kind == 'neg':
            v = evaluate(node[1])
            return v if isinstance(v, str) else -v
        if kind == 'bin':
            _, op, left, right = node
            lv = evaluate(left)
            if isinstance(lv, str):
                return lv
            rv = evaluate(right)
            if isinstance(rv, str):
                return rv
            if op == '+':
                return lv + rv
            if op == '-':
                return lv - rv
            if op == '*':
                return lv * rv
            if rv == 0:
                return '#DIV/0!'
            q = abs(lv) // abs(rv)
            return -q if (lv < 0) != (rv < 0) else q
        if kind == 'if':
            _, op, left, right, then, other = node
            lv = evaluate(left)
            if isinstance(lv, str):
                return lv
            rv = evaluate(right)
            if isinstance(rv, str):
                return rv
            return evaluate(then) if compare[op](lv, rv) else evaluate(other)
        if kind == 'call':
            _, fname, args = node
            nums = []
            for arg in args:
                if arg[0] == 'range':
                    for name in range_cells(arg[1], arg[2]):
                        v = cell_value(name)
                        if isinstance(v, str):
                            return v
                        nums.append(v)
                else:
                    v = evaluate(arg[1])
                    if isinstance(v, str):
                        return v
                    nums.append(v)
            if not nums:
                return 0
            if fname == 'SUM':
                return sum(nums)
            if fname == 'MIN':
                return min(nums)
            return max(nums)
        raise ValueError(kind)

    return {name: cell_value(name) for name in cells}
